const product = (
  id: string,
  companySlug: WaveFourteenCompanySlug,
  name: string,
  url: string,
  type: ReturnType<typeof l>,
  sourceRows = [] as ReturnType<typeof rows>,
  category: WaveFourteenProductSeed["category"] = "robot-platform",
  primary = category === "end-effector" ? "manipulator-end-effector" : category === "motion" ? "motion-transmission" : category === "model-software" ? "software-tools" : "robot-platform",
  subclass = "humanoid-robot",
  coverage: WaveFourteenProductSeed["coverage"] = sourceRows.length ? "official-partial" : "capability-only",
  level: WaveFourteenProductSeed["level"] = "model",
): WaveFourteenProductSeed => ({
  ...capabilityProduct(id, companySlug, name, url, category, primary, subclass, type,
    [l(`${name} 是厂商当前目录中的${type.zh}，本记录按其公开型号、配置与用途独立建档。`, `${name} is a ${type.en} in the manufacturer's current catalog, recorded separately by published model, configuration, and application.`), l("参数仅沿用到来源明确覆盖的型号与配置；系列共性、选件和峰值条件不会自动当作所有版本的额定值。", "Specifications apply only to the model and configuration explicitly covered by the source; family features, options, and peak conditions are not treated as ratings for every edition.")],
    [l("实际适用性需要按工况、接口与交付配置验证。", "Actual fit requires validation against duty, interfaces, and delivered configuration.")],
    l("核对控制、通信、机械、电气、软件与系统集成边界。", "Verify control, communications, mechanical, electrical, software, and integration boundaries."),
    l("核对版本、额定/峰值条件、选件、寿命、安全与商业状态。", "Verify revision, rated/peak conditions, options, life, safety, and commercial status."),
    ["research", "manufacturing", "logistics", "integration"], sourceRows),
  rows: sourceRows,
  coverage,
  specificationKind: sourceRows.length ? "parameters" : "capabilities",
  level,
});

